import settings


def test_serverchan_config_is_dict():
    assert isinstance(settings.SERVERCHAN_CONFIG, dict)


def test_serverchan_config_has_required_keys():
    required_keys = {'enabled', 'sendkey', 'use_email'}
    assert required_keys.issubset(set(settings.SERVERCHAN_CONFIG.keys()))


def test_serverchan_config_enabled_default():
    assert settings.SERVERCHAN_CONFIG['enabled'] is True


def test_serverchan_config_sendkey_default():
    assert settings.SERVERCHAN_CONFIG['sendkey'] == ''


def test_serverchan_config_use_email_default():
    assert settings.SERVERCHAN_CONFIG['use_email'] is False


def test_existing_smtp_config_unchanged():
    assert settings.SMTP_CONFIG['host'] == 'smtp.qq.com'
    assert settings.SMTP_CONFIG['port'] == 465


def test_existing_latex_config_unchanged():
    assert settings.LATEX_RENDER_CONFIG['enabled'] is True
    assert settings.LATEX_RENDER_CONFIG['dpi'] == 300
